function fail(message){return [{json:{ok:false,message}}];}
let body; try { const raw=$json.body||$json; body=typeof raw==='string'?JSON.parse(raw):raw; } catch(e){ return fail('La solicitud no tiene formato valido.'); }
const empresaId=String(body.empresaId||'').trim();
if(!empresaId)return fail('Falta empresaId.');
const esc=(v)=>String(v).replace(/"/g,'\\"');
const conditions=['{EmpresaId} = "'+esc(empresaId)+'"'];
if(body.usuarioId) conditions.push('{UsuarioId} = "'+esc(body.usuarioId)+'"');
if(body.cajaSesionId) conditions.push('{CajaSesionId} = "'+esc(body.cajaSesionId)+'"');
if(body.estado) conditions.push('{Estado} = "'+esc(String(body.estado).toUpperCase())+'"');
if(body.fechaDesde) conditions.push('IS_AFTER({Fecha}, "'+esc(body.fechaDesde)+'")');
if(body.fechaHasta) conditions.push('IS_BEFORE({Fecha}, "'+esc(body.fechaHasta)+'")');
const term=String(body.busqueda||'').trim();
if(term){ const t=esc(term.toLowerCase()); conditions.push('OR(FIND("'+t+'", LOWER({OperationId}&"")), FIND("'+t+'", LOWER({ClienteNombre}&"")), FIND("'+t+'", LOWER(RECORD_ID()&"")))'); }
return [{json:{ok:true,formula:'AND('+conditions.join(',')+')'}}];

const ventas=$items('Buscar Ventas').filter(item=>item.json&&item.json.id);
if(ventas.length===0)return [{json:{ok:true,ventas:[],detailFormula:'FALSE()'}}];
const ids=ventas.map(item=>item.json.id);
const or=ids.map(id=>'FIND("'+id+'", ARRAYJOIN({Venta}))').join(',');
return [{json:{ok:true,ventaIds:ids,detailFormula:'OR('+or+')'}}];

const ventaItems=$items('Buscar Ventas').filter(item=>item.json&&item.json.id);
const detailItems=$items('Buscar Detalle Venta').filter(item=>item.json&&item.json.id);
const detailsBySale=new Map();
for(const item of detailItems){ const f=item.json.fields||item.json; const ventaRef=Array.isArray(f.Venta)?f.Venta[0]:String(f.Venta||''); if(!detailsBySale.has(ventaRef))detailsBySale.set(ventaRef,[]); detailsBySale.get(ventaRef).push({ detalleId:item.json.id, productoId:Array.isArray(f.Producto)?f.Producto[0]:f.Producto, producto:f.ProductoNombre, codigoBarras:f.CodigoBarras, cantidad:Number(f.Cantidad||0), precioUnitario:Number(f.PrecioUnitario||0), totalLinea:Number(f.TotalLinea||0), estado:f.Estado }); }
const ventas=ventaItems.map(item=>{ const f=item.json.fields||item.json; return { ventaId:item.json.id, operationId:f.OperationId||'', empresaId:f.EmpresaId||'', usuarioId:f.UsuarioId||f.Cajero||'', cajaSesionId:f.CajaSesionId||'', fechaHora:f.Fecha||'', cliente:f.ClienteNombre||'Consumidor final', formaPago:f.MetodoPago||'', subtotal:Number(f.Subtotal||0), total:Number(f.Total||0), estado:String(f.Estado||'').toUpperCase(), detalle:detailsBySale.get(item.json.id)||[] }; });
ventas.sort((a,b)=>new Date(b.fechaHora||0)-new Date(a.fechaHora||0));
return [{json:{ok:true,ventas}}];
